# Real Money build, step 148 (after rmv144.py): four of the owner's own photos added to the library.
#  Pets: "Morning run" (Labrador on the dunes). Nature: "Golden cliff", "Sea of flowers", "Desert pause".
#  Cropped to 3:4 portrait from phone screenshots. (Lefkada cave photo left out: children in it.)
import os, json
d = os.environ.get('YOFI_DIR', os.path.dirname(os.path.abspath(__file__)) + '/')
s = open(d + 'yofi-real.html').read()
NEW = json.loads('[{"id": "owndog", "title": "Morning run", "cat": "Pets", "src": "data:image/jpeg;base64,"}, {"id": "owncliff", "title": "Golden cliff", "cat": "Nature", "src": "data:image/jpeg;base64,"}, {"id": "ownflowers", "title": "Sea of flowers", "cat": "Nature", "src": "data:image/jpeg;base64,"}, {"id": "owndesert", "title": "Desert pause", "cat": "Nature", "src": "data:image/jpeg;base64,"}]')
i = s.index('const SEED = ['); j = s.index('];', i)
arr = json.loads(s[i + len('const SEED = '):j + 1])
arr = [x for x in arr if x.get('id') not in {n['id'] for n in NEW}] + NEW
s = s[:i] + 'const SEED = ' + json.dumps(arr, separators=(',', ':')) + s[j + 1:]
open(d + 'yofi-real.html', 'w').write(s); print('rm v145 ok')
